16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.NotEmpty;
22	import jakarta.validation.constraints.Pattern;
23	
24	import java.time.LocalDate;
25	import java.util.*;
26	
27	/**
28	 * Simple JavaBean domain object representing an owner.
29	 *
30	 * @author Ken Krebs
31	 * @author Juergen Hoeller
32	 * @author Sam Brannen
33	 * @author Michael Isvy
34	 */
35	@Entity
36	@Table(name = "owners")
37	public class Owner extends Person {
38	    @Column(name = "address")
39	    @NotEmpty
40	    private String address;
41	
42	    @Column(name = "city")
43	    @NotEmpty
44	    private String city;
45	
46	    @Column(name = "telephone")
47	    @NotEmpty
48	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Phone number must be in E.164 form (+ followed by 8 to 15 digits)")
49	    private String telephone;
50	
51	    @Column(name = "email")
52	    private String email;
53	
54	    @Column(name = "registration_date")
55	    private LocalDate registrationDate;
56	
57	    @Column(name = "customer_code")
58	    private String customerCode;
59	
60	    @Column(name = "household_id")
61	    private String householdId;
62	
63	    @Column(name = "namesake_count")
64	    private Integer namesakeCount;
65	
66	    @Transient
67	    private boolean bulkSignupWarning;
68	
69	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
70	    private Set<Pet> pets;
71	
72	    public String getAddress() {
73	        return this.address;
74	    }
75	
76	    public void setAddress(String address) {
77	        this.address = address;
78	    }
79	
80	    public String getCity() {
81	        return this.city;
82	    }
83	
84	    public void setCity(String city) {
85	        this.city = city;
86	    }
87	
88	    public String getTelephone() {
89	        return this.telephone;
90	    }
91	
92	    public void setTelephone(String telephone) {
93	        this.telephone = telephone;
94	    }
95	
96	    public String getEmail() {
97	        return this.email;
98	    }
99	
100	    public void setEmail(String email) {
101	        this.email = email;
102	    }
103	
104	    public LocalDate getRegistrationDate() {
105	        return this.registrationDate;
106	    }
107	
108	    public void setRegistrationDate(LocalDate registrationDate) {
109	        this.registrationDate = registrationDate;
110	    }
111	
112	    public String getCustomerCode() {
113	        return this.customerCode;
114	    }
115	
116	    public void setCustomerCode(String customerCode) {
117	        this.customerCode = customerCode;
118	    }
119	
120	    public String getHouseholdId() {
121	        return this.householdId;
122	    }
123	
124	    public void setHouseholdId(String householdId) {
125	        this.householdId = householdId;
126	    }
127	
128	    public Integer getNamesakeCount() {
129	        return this.namesakeCount;
130	    }
131	
132	    public void setNamesakeCount(Integer namesakeCount) {
133	        this.namesakeCount = namesakeCount;
134	    }
135	
136	    /**
137	     * The owner's name formatted as {@code 'LastName, FirstName'} from the stored names.
138	     * Not persisted — derived from {@link #getLastName()} and {@link #getFirstName()}.
139	     */
140	    @Transient
141	    public String getDisplayName() {
142	        return this.getLastName() + ", " + this.getFirstName();
143	    }
144	
145	    /**
146	     * The owner's initials: the upper-cased first letters of firstName and lastName,
147	     * dot-separated with a trailing dot (e.g. {@code 'J.S.'}).
148	     * Not persisted — derived from {@link #getFirstName()} and {@link #getLastName()}.
149	     */
150	    @Transient
151	    public String getInitials() {
152	        return Character.toUpperCase(this.getFirstName().charAt(0)) + "."
153	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
154	    }
155	
156	    /**
157	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where YY is
158	     * the last two digits of the {@link #getRegistrationDate() registrationDate} year
159	     * (e.g. {@code 'LON-SMI-0007-M26'}).
160	     * Not persisted — derived from {@link #getCustomerCode()} and {@link #getRegistrationDate()}.
161	     */
162	    @Transient
163	    public String getMembershipNumber() {
164	        return this.customerCode + "-M" + String.format("%02d", this.registrationDate.getYear() % 100);
165	    }
166	
167	    /**
168	     * The owner's membership tier: {@code 'SILVER'} when {@link #getNamesakeCount() namesakeCount}
169	     * is 0 and an {@link #getEmail() email} is present, otherwise {@code 'BRONZE'}.
170	     * Not persisted — derived from {@link #getNamesakeCount()} and {@link #getEmail()}.
171	     */
172	    @Transient
173	    public String getMembershipTier() {
174	        boolean uniqueName = this.namesakeCount != null && this.namesakeCount == 0;
175	        boolean hasEmail = this.email != null && !this.email.isBlank();
176	        return (uniqueName && hasEmail) ? "SILVER" : "BRONZE";
177	    }
178	
179	    /**
180	     * Fixed city-to-region table used to derive {@link #getLocality() locality}.
181	     */
182	    private static final Map<String, String> CITY_REGION = Map.of(
183	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
184	
185	    /**
186	     * The owner's locality: the canonical region derived from {@link #getCity() city}
187	     * using the fixed {@link #CITY_REGION} table (Sydney->NSW, Melbourne->VIC,
188	     * Brisbane->QLD), or {@code 'UNKNOWN'} when the city is not in the table.
189	     * Not persisted — derived from {@link #getCity()}.
190	     */
191	    @Transient
192	    public String getLocality() {
193	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
194	    }
195	
196	    /**
197	     * Whether more than 80 owners had already been created today when this response was
198	     * built. Not persisted — populated for the response by the create and fetch pipelines
199	     * and defaults to {@code false} so every owner serialization carries the flag.
200	     */
201	    @Transient
202	    public boolean isBulkSignupWarning() {
203	        return this.bulkSignupWarning;
204	    }
205	
206	    public void setBulkSignupWarning(boolean bulkSignupWarning) {
207	        this.bulkSignupWarning = bulkSignupWarning;
208	    }
209	
210	    protected Set<Pet> getPetsInternal() {
211	        if (this.pets == null) {
212	            this.pets = new HashSet<>();
213	        }
214	        return this.pets;
215	    }
216	
217	    protected void setPetsInternal(Set<Pet> pets) {
218	        this.pets = pets;
219	    }
220	
221	    public List<Pet> getPets() {
222	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
223	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
224	        return Collections.unmodifiableList(sortedPets);
225	    }
226	
227	    public void setPets(List<Pet> pets) {
228	        this.pets = new HashSet<>(pets);
229	    }
230	
231	    public void addPet(Pet pet) {
232	        getPetsInternal().add(pet);
233	        pet.setOwner(this);
234	    }
235	
236	    /**
237	     * Return the Pet with the given name, or null if none found for this Owner.
238	     *
239	     * @param name to test
240	     * @return true if pet name is already in use
241	     */
242	    public Pet getPet(String name) {
243	        return getPet(name, false);
244	    }
245	
246	    /**
247	     * Return the Pet with the given name, or null if none found for this Owner.
248	     *
249	     * @param name to test
250	     * @return true if pet name is already in use
251	     */
252	    public Pet getPet(String name, boolean ignoreNew) {
253	        name = name.toLowerCase();
254	        for (Pet pet : getPetsInternal()) {
255	            if (!ignoreNew || !pet.isNew()) {
256	                String compName = pet.getName();
257	                compName = compName.toLowerCase();
258	                if (compName.equals(name)) {
259	                    return pet;
260	                }
261	            }
262	        }
263	        return null;
264	    }
265	
266	    public Pet getPet(Integer petId) {
267	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
268	    }
269	
270	    @Override
271	    public String toString() {
272	        return new ToStringCreator(this)
273	
274	            .append("id", this.getId())
275	            .append("new", this.isNew())
276	            .append("lastName", this.getLastName())
277	            .append("firstName", this.getFirstName())
278	            .append("address", this.address)
279	            .append("city", this.city)
280	            .append("telephone", this.telephone)
281	            .toString();
282	    }
283	}
