1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateTelephoneException;
8	
9	/**
10	 * Runs after {@link ValidateNewOwner} (which has normalized the telephone to E.164 form)
11	 * and before {@link BuildOwner}. Rejects the create with a 409 when any existing owner shares
12	 * the same E.164 telephone, so no two owners can share a phone number. Publishes nothing;
13	 * it is a validation gate that only escalates on conflict.
14	 */
15	public class ValidateUniqueTelephone {
16	
17	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
18	            throws DuplicateTelephoneException {
19	        String telephone = request.getTelephone();
20	        for (Owner existing : ownerRepository.findAll()) {
21	            if (telephone.equals(OwnerTelephone.normalize(existing.getTelephone()))) {
22	                throw new DuplicateTelephoneException(
23	                        "Telephone " + telephone + " is already used by another owner");
24	            }
25	        }
26	    }
27	}
