1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.util.List;
4	
5	import net.officefloor.plugin.variable.Out;
6	import net.officefloor.plugin.variable.Val;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.repository.OwnerRepository;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.escalation.DuplicateHouseholdException;
11	
12	/**
13	 * Runs after {@link ValidateUniqueTelephone} and before {@link BuildOwner}. A read-only
14	 * validation gate: it detects whether the new owner would join an existing household (see
15	 * {@link Household}) and decides allow or reject, writing nothing to the database.
16	 *
17	 * <p>When another owner already shares the household and the request did not opt in with
18	 * {@code sharesHousehold = true}, rejects the create with a 409. Otherwise it publishes the
19	 * {@link Household.Id} for the rest of the pipeline — the shared identifier when joining a
20	 * household, {@link Household.Id#ABSENT} when not — leaving {@link ApplySharedHousehold} to
21	 * back-fill existing members and {@link BuildOwner} to stamp the new owner.
22	 */
23	public class ValidateUniqueHousehold {
24	
25	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository,
26	            Out<Household.Id> householdIdOut) throws DuplicateHouseholdException {
27	        List<Owner> members = Household.membersOf(request, ownerRepository);
28	        if (members.isEmpty()) {
29	            // Not joining any household: nothing to share, nothing to reject.
30	            householdIdOut.set(Household.Id.ABSENT);
31	            return;
32	        }
33	        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
34	            throw new DuplicateHouseholdException("An owner named " + request.getLastName()
35	                    + " already exists at " + request.getAddress());
36	        }
37	        householdIdOut.set(Household.idFor(request));
38	    }
39	}
