1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Out;
4	import net.officefloor.plugin.variable.Val;
5	import org.springframework.samples.petclinic.mapper.OwnerMapper;
6	import org.springframework.samples.petclinic.model.Owner;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.samples.petclinic.repository.OwnerRepository;
9	
10	public class BuildOwner {
11	
12	    public void service(@Val OwnerFieldsDto request, @Val Household.Id householdId,
13	            OwnerMapper ownerMapper, OwnerRepository ownerRepository, Out<Owner> built) {
14	        Owner owner = ownerMapper.toOwner(request);
15	        // The effective registration date defaults an unsupplied value to the server's
16	        // current date, then rolls any weekend forward to the next Monday so derived values
17	        // (e.g. the membership number's year) use the adjusted business day.
18	        owner.setRegistrationDate(BusinessDay.effectiveRegistrationDate(owner.getRegistrationDate()));
19	        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName(), ownerRepository));
20	        // Record how many existing owners already share this first+last name (case-insensitive),
21	        // counted before this owner is persisted so the value is fixed at creation time.
22	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName(), ownerRepository));
23	        // Join a shared household when the gate resolved an identifier.
24	        if (householdId != null && householdId.isPresent()) {
25	            owner.setHouseholdId(householdId.value());
26	        }
27	        built.set(owner);
28	    }
29	
30	    /**
31	     * Build the '<CITY3>-<LAST3>-<NNNN>' customer code: CITY3 is the upper-cased first three
32	     * letters of the city, LAST3 the upper-cased first three letters of the last name, and NNNN
33	     * a per-city 4-digit zero-padded sequence equal to one more than the number of owners
34	     * already in that city (e.g. 'LON-SMI-0007').
35	     */
36	    private static String nextCustomerCode(String city, String lastName, OwnerRepository ownerRepository) {
37	        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
38	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
39	        int sequence = countOwnersInCity(city, ownerRepository) + 1;
40	        return String.format("%s-%s-%04d", city3, last3, sequence);
41	    }
42	
43	    /**
44	     * Count the existing owners in the given city, compared case-insensitively.
45	     */
46	    private static int countOwnersInCity(String city, OwnerRepository ownerRepository) {
47	        int count = 0;
48	        for (Owner existing : ownerRepository.findAll()) {
49	            if (city.equalsIgnoreCase(existing.getCity())) {
50	                count++;
51	            }
52	        }
53	        return count;
54	    }
55	
56	    /**
57	     * Count the existing owners whose first and last names both match the given names,
58	     * compared case-insensitively.
59	     */
60	    private static int countNamesakes(String firstName, String lastName,
61	            OwnerRepository ownerRepository) {
62	        int count = 0;
63	        for (Owner existing : ownerRepository.findAll()) {
64	            if (firstName.equalsIgnoreCase(existing.getFirstName())
65	                    && lastName.equalsIgnoreCase(existing.getLastName())) {
66	                count++;
67	            }
68	        }
69	        return count;
70	    }
71	}
