package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;

import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

/**
 * Shared household rules for the owner-create pipeline. A household is the set of owners with
 * the same last name at the same address, compared case-insensitively with collapsed
 * whitespace. The membership match and the stable identifier are defined once here so the gate
 * ({@link ValidateUniqueHousehold}), the back-fill ({@link ApplySharedHousehold}) and the new
 * owner ({@link BuildOwner}) all agree on them.
 */
final class Household {

    private Household() {
    }

    /**
     * The household identifier published between steps. A dedicated type keeps the variable
     * unambiguous (OfficeFloor matches variables by type) and distinct from other strings in
     * the pipeline. {@link #ABSENT} (an empty value) means the new owner is not joining a
     * shared household.
     */
    record Id(String value) {

        static final Id ABSENT = new Id("");

        boolean isPresent() {
            return this.value != null && !this.value.isBlank();
        }
    }

    /**
     * Existing owners that share the request's household (same normalized last name and
     * address).
     */
    static List<Owner> membersOf(OwnerFieldsDto request, OwnerRepository ownerRepository) {
        String lastName = normalize(request.getLastName());
        String address = OwnerAddress.normalize(request.getAddress());
        List<Owner> members = new ArrayList<>();
        for (Owner existing : ownerRepository.findAll()) {
            if (lastName.equals(normalize(existing.getLastName()))
                    && address.equals(OwnerAddress.normalize(existing.getAddress()))) {
                members.add(existing);
            }
        }
        return members;
    }

    /**
     * Stable identifier for the request's household: the first 12 upper-case hex characters of
     * the SHA-256 of the normalized last name and address, so every owner in the same household
     * derives the same value regardless of creation order.
     */
    static Id idFor(OwnerFieldsDto request) {
        String seed = normalize(request.getLastName()) + "\n" + OwnerAddress.normalize(request.getAddress());
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256")
                    .digest(seed.getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder();
            for (int i = 0; i < 6; i++) {
                sb.append(String.format("%02X", digest[i]));
            }
            return new Id(sb.toString());
        }
        catch (NoSuchAlgorithmException ex) {
            throw new IllegalStateException("SHA-256 not available", ex);
        }
    }

    /**
     * Normalize a name or address for household comparison: trim, collapse any run of
     * whitespace to a single space, and lower-case. Yields {@code ""} for a {@code null} input.
     */
    private static String normalize(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }
}
=== ValidateUniqueHousehold ===
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.List;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateHouseholdException;

/**
 * Runs after {@link ValidateUniqueTelephone} and before {@link BuildOwner}. A read-only
 * validation gate: it detects whether the new owner would join an existing household (see
 * {@link Household}) and decides allow or reject, writing nothing to the database.
 *
 * <p>When another owner already shares the household and the request did not opt in with
 * {@code sharesHousehold = true}, rejects the create with a 409. Otherwise it publishes the
 * {@link Household.Id} for the rest of the pipeline — the shared identifier when joining a
 * household, {@link Household.Id#ABSENT} when not — leaving {@link ApplySharedHousehold} to
 * back-fill existing members and {@link BuildOwner} to stamp the new owner.
 */
public class ValidateUniqueHousehold {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository,
            Out<Household.Id> householdIdOut) throws DuplicateHouseholdException {
        List<Owner> members = Household.membersOf(request, ownerRepository);
        if (members.isEmpty()) {
            // Not joining any household: nothing to share, nothing to reject.
            householdIdOut.set(Household.Id.ABSENT);
            return;
        }
        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
            throw new DuplicateHouseholdException("An owner named " + request.getLastName()
                    + " already exists at " + request.getAddress());
        }
        householdIdOut.set(Household.idFor(request));
    }
}
=== ApplySharedHousehold ===
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

/**
 * Runs after the {@link ValidateUniqueHousehold} gate and before {@link BuildOwner}, under
 * {@code govern: [ transaction ]}. When the gate resolved a shared {@link Household.Id} (the new
 * owner is joining an existing household), back-fills that identifier onto every existing member
 * that is missing it, so the whole household carries the same stable id. A no-op — publishing
 * nothing and touching no rows — when the new owner is not joining a shared household.
 */
public class ApplySharedHousehold {

    public void service(@Val OwnerFieldsDto request, @Val Household.Id householdId,
            OwnerRepository ownerRepository) {
        if (householdId == null || !householdId.isPresent()) {
            return;
        }
        for (Owner member : Household.membersOf(request, ownerRepository)) {
            if (!householdId.value().equals(member.getHouseholdId())) {
                member.setHouseholdId(householdId.value());
                ownerRepository.save(member);
            }
        }
    }
}
=== BuildOwner ===
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.mapper.OwnerMapper;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.repository.OwnerRepository;

public class BuildOwner {

    public void service(@Val OwnerFieldsDto request, @Val Household.Id householdId,
            OwnerMapper ownerMapper, OwnerRepository ownerRepository, Out<Owner> built) {
        Owner owner = ownerMapper.toOwner(request);
        // The effective registration date defaults an unsupplied value to the server's
        // current date, then rolls any weekend forward to the next Monday so derived values
        // (e.g. the membership number's year) use the adjusted business day.
        owner.setRegistrationDate(BusinessDay.effectiveRegistrationDate(owner.getRegistrationDate()));
        owner.setCustomerCode(nextCustomerCode(owner.getCity(), owner.getLastName(), ownerRepository));
        // Record how many existing owners already share this first+last name (case-insensitive),
        // counted before this owner is persisted so the value is fixed at creation time.
        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName(), ownerRepository));
        // Join a shared household when the gate resolved an identifier.
        if (householdId != null && householdId.isPresent()) {
            owner.setHouseholdId(householdId.value());
        }
        built.set(owner);
    }

    /**
     * Build the '<CITY3>-<LAST3>-<NNNN>' customer code: CITY3 is the upper-cased first three
     * letters of the city, LAST3 the upper-cased first three letters of the last name, and NNNN
     * a per-city 4-digit zero-padded sequence equal to one more than the number of owners
     * already in that city (e.g. 'LON-SMI-0007').
     */
    private static String nextCustomerCode(String city, String lastName, OwnerRepository ownerRepository) {
        String city3 = city.substring(0, Math.min(3, city.length())).toUpperCase();
        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
        int sequence = countOwnersInCity(city, ownerRepository) + 1;
        return String.format("%s-%s-%04d", city3, last3, sequence);
    }

    /**
     * Count the existing owners in the given city, compared case-insensitively.
     */
    private static int countOwnersInCity(String city, OwnerRepository ownerRepository) {
        int count = 0;
        for (Owner existing : ownerRepository.findAll()) {
            if (city.equalsIgnoreCase(existing.getCity())) {
                count++;
            }
        }
        return count;
    }

    /**
     * Count the existing owners whose first and last names both match the given names,
     * compared case-insensitively.
     */
    private static int countNamesakes(String firstName, String lastName,
            OwnerRepository ownerRepository) {
        int count = 0;
        for (Owner existing : ownerRepository.findAll()) {
            if (firstName.equalsIgnoreCase(existing.getFirstName())
                    && lastName.equalsIgnoreCase(existing.getLastName())) {
                count++;
            }
        }
        return count;
    }
}
